{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyOstLkcYhdJsRu9gV1anRbs"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":4,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"fq-aeP-61YjP","executionInfo":{"status":"ok","timestamp":1794390069871,"user_tz":-420,"elapsed":4351,"user":{"displayName":"Hisyam Fithroturrohim","userId":"09005319930458663373"}},"outputId":"58557dc6-918c-477d-8c5b-3a28b336399a"},"outputs":[{"output_type":"stream","name":"stdout","text":["Masukkan jumlah kandidat PIN (N): 1\n","Kandidat PIN ke -1: 123456\n","PIN ke -1 skornya 4, tergolong Lemah.\n","Rekap: Kuat 0 , Sedang 0 , Lemah 1\n"]}],"source":["\n","# Nama/NIM  : Hisyam Fithroturrohim 15626049\n","# Tanggal   : 11 November 2026\n","# Deskripsi : Praktikum Berpikir Komputasional Modul 4 (Menghitung skor dan kekuatan PIN)\n","\n","def hitung_pin(pin):\n","    skor = 0\n","\n","    digit = []\n","    for karakter in pin:\n","        if karakter.isdigit() and karakter not in digit:\n","            digit.append(karakter)\n","    skor = skor + len(digit) * 4\n","\n","    for karakter in pin:\n","        if karakter.isupper():\n","            skor = skor + 10\n","            break\n","\n","    if len(pin) >= 8:\n","        skor = skor + 15\n","    elif len(pin) >= 6:\n","        skor = skor + 5\n","\n","    for i in range(len(pin) - 1):\n","        if pin[i].isdigit() and pin[i + 1].isdigit():\n","            selisih = int(pin[i]) - int(pin[i + 1])\n","\n","            if selisih == 1 or selisih == -1:\n","                skor = skor - 5\n","    return skor\n","\n","def hasil(skor):\n","    if skor >= 40:\n","        return \"Kuat\"\n","    elif skor >= 20:\n","        return \"Sedang\"\n","    else:\n","        return \"Lemah\"\n","\n","N = int(input(\"Masukkan jumlah kandidat PIN (N): \"))\n","\n","kuat = 0\n","sedang = 0\n","lemah = 0\n","\n","for i in range(1, N + 1):\n","    pin = input(\"Kandidat PIN ke -\" + str(i) + \": \")\n","\n","    skor = hitung_pin(pin)\n","    kategori = hasil(skor)\n","\n","    print(\"PIN ke -\" + str(i) + \" skornya \" + str(skor) + \", tergolong \" + kategori + \".\")\n","\n","    if kategori == \"Kuat\":\n","        kuat = kuat + 1\n","    elif kategori == \"Sedang\":\n","        sedang = sedang + 1\n","    else:\n","        lemah = lemah + 1\n","\n","print(\"Rekap: Kuat\", kuat, \", Sedang\", sedang, \", Lemah\", lemah)"]}]}